pub fn error_policy(reason: &str) -> Option<&'static ErrorPolicy> {
    ERROR_REASON_POLICIES.iter().find(|row| row.reason == reason)
}

pub fn normalize_error_reason(values: &[&str]) -> &'static str {
    for value in values {
        let candidate = value.trim().split(':').next().unwrap_or("");
        if let Some(policy) = error_policy(candidate) { return policy.reason; }
        if let Some((_, reason)) = ERROR_REASON_ALIASES.iter().find(|(alias, _)| alias.eq_ignore_ascii_case(candidate)) { return *reason; }
    }
    "hook_handler_failed"
}
